<script>
import {onMount} from 'svelte';
import {SERVICES,DEADLINES} from '../lib/catalog.js';import Icon from '../lib/components/Icon.svelte';
let {params=new URLSearchParams()}=$props();let category=$state('All services');onMount(()=>category=params.get('category')??'All services');let query=$state('');
let selected=$derived(['All services','Records','Planning','Advising','Graduation','Support'].find(c=>c.toLowerCase()===category.toLowerCase())??'All services');let results=$derived(SERVICES.filter(s=>(selected==='All services'||s.category===selected)&&`${s.title} ${s.description}`.toLowerCase().includes(query.toLowerCase())));
</script>
<div class="page-heading"><div><p class="eyebrow">Support, without the search party</p><h1>Academic services</h1><p>Your records, important dates, and next steps — in one place.</p></div></div>
<div class="search-box service-search"><Icon name="search"/><input type="search" aria-label="Find a student service" placeholder="What can we help you find?" bind:value={query}/></div>
<div class="category-chips" aria-label="Service category">{#each ['All services','Records','Planning','Advising','Graduation','Support'] as c}<button class:active={selected===c} aria-pressed={selected===c} onclick={()=>category=c}>{c}</button>{/each}</div>
<div class="results-meta" role="status"><span>{results.length} services</span><span>External links open official university websites</span></div><div class="services-grid">{#each results as s}<a class="service-card panel" href={s.href} target={s.external?'_blank':undefined} rel={s.external?'noreferrer':undefined}><span class="tile-icon"><Icon name={s.icon} size={24}/></span><span class="eyebrow">{s.category}</span><h2>{s.title}</h2><p>{s.description}</p><strong>{s.action}<Icon name={s.external?'external':'arrow'} size={16}/></strong></a>{/each}</div>{#if !results.length}<div class="empty-state panel"><Icon name="search" size={30}/><h2>Let’s try another search.</h2><p>Try a broader phrase or browse all services.</p><button class="button secondary" onclick={()=>{category='All services';query='';}}>Show all services</button></div>{/if}
<section class="panel padded spaced"><div class="section-heading"><div><h2>Dates to keep in view</h2><p class="muted small">Illustrative planning milestones. Confirm all official deadlines with UC.</p></div><a href="https://www.uc.edu/about/registrar/calendars.html" target="_blank" rel="noreferrer" class="text-link">Official calendar<Icon name="external" size={16}/></a></div>{#each DEADLINES as d}<div class="deadline-row"><div class="date-tile"><strong>{d.day}</strong><span>{d.month}</span></div><div><strong>{d.title}</strong><p class="muted small">{d.detail}</p></div><span class="badge neutral">{d.type}</span></div>{/each}</section>
